struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;

    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    TreeNode* recoverFromPreorder(string traversal) {
        vector<TreeNode*> stack;
        int i = 0;

        while (i < (int)traversal.size()) {
            int depth = 0;
            while (i < (int)traversal.size() && traversal[i] == '-') {
                depth++;
                i++;
            }

            int value = 0;
            while (i < (int)traversal.size() && traversal[i] >= '0' && traversal[i] <= '9') {
                value = value * 10 + (traversal[i] - '0');
                i++;
            }

            TreeNode* node = new TreeNode(value);

            while ((int)stack.size() > depth) {
                stack.pop_back();
            }

            if (!stack.empty()) {
                TreeNode* parent = stack.back();
                if (parent->left == nullptr) {
                    parent->left = node;
                } else {
                    parent->right = node;
                }
            }

            stack.push_back(node);
        }

        return stack.front();
    }
};

