    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

struct TreeNode* recoverFromPreorder(char* traversal) {
    struct TreeNode* stack[1000];
    int top = -1;
    int i = 0;

    while (traversal[i] != '\0') {
        int depth = 0;
        while (traversal[i] == '-') {
            depth++;
            i++;
        }

        int value = 0;
        while (traversal[i] >= '0' && traversal[i] <= '9') {
            value = value * 10 + (traversal[i] - '0');
            i++;
        }

        struct TreeNode* node = newNode(value);

        while (top + 1 > depth) {
            top--;
        }

        if (top >= 0) {
            if (stack[top]->left == NULL) {
                stack[top]->left = node;
            } else {
                stack[top]->right = node;
            }
        }

        stack[++top] = node;
    }

    return stack[0];
}

